/**
 * Single source of truth for the 3D stage: orientation, framing and canonical views.
 *
 * Measured from the exported meshes (see `data/model-bounds.json`, regenerated by
 * `npm run assets:bounds`):
 *   body bbox  x −0.568…0.568   y 0…1.86   z −0.114…0.363
 *   eyes       z +0.115…0.146   toes z +0.212   shoulder blades / glutes at −Z
 *
 * The characters therefore face **+Z**. Cameras and key lights are derived from
 * that fact rather than hard-coded per component, so no view can silently end up
 * on the wrong side of the body.
 */

export type StudioViewId = 'front' | 'back' | 'left' | 'right';

/** Direction the character faces, in world space. */
export const CHARACTER_FORWARD: readonly [number, number, number] = [0, 0, 1];

/** Height of the characters in metres, used for framing maths. */
export const CHARACTER_HEIGHT_M = 1.86;

/** Vertical field of view used by the studio and the hero. */
export const STUDIO_FOV = 30;
export const HERO_FOV = 32;

/** Point the camera orbits: just below the sternum, the visual centre of mass. */
export const STUDIO_TARGET: readonly [number, number, number] = [0, 0.93, 0];

/**
 * Distance that fits the full character plus a margin into the vertical FOV.
 * `margin` is a multiplier on the character height (1.14 = 14 % headroom).
 */
export function framingDistance(heightM = CHARACTER_HEIGHT_M, fov = STUDIO_FOV, margin = 1.14): number {
  const halfFov = (fov * Math.PI) / 360;
  return (heightM * margin) / 2 / Math.tan(halfFov);
}

/** Default orbit distance — derived from the geometry, never guessed. */
export const STUDIO_DISTANCE = Number(framingDistance().toFixed(2));

/** Orbit limits: close enough to inspect a forearm, far enough to see the feet. */
export const STUDIO_MIN_DISTANCE = 1.7;
export const STUDIO_MAX_DISTANCE = Number((STUDIO_DISTANCE * 1.35).toFixed(2));

const FRONT = Math.sign(CHARACTER_FORWARD[2]) || 1;
const EYE_Y = STUDIO_TARGET[1] + 0.12;

/** Camera positions for the four canonical studio views. */
export const STUDIO_VIEWS: Record<StudioViewId, readonly [number, number, number]> = {
  front: [0, EYE_Y, FRONT * STUDIO_DISTANCE],
  back: [0, EYE_Y, -FRONT * STUDIO_DISTANCE],
  // the character's left is +X when facing +Z (left = up × forward)
  left: [FRONT * STUDIO_DISTANCE, EYE_Y, 0],
  right: [-FRONT * STUDIO_DISTANCE, EYE_Y, 0],
};

/** Key light: in front of the character and above, matching the front camera. */
export const KEY_LIGHT_POSITION: readonly [number, number, number] = [-2.4, 3.9, FRONT * 2.9];

export interface FramingResult {
  distance: number;
  visibleHeight: number;
  /** Full body visible, feet not cropped. */
  ok: boolean;
  /** Extra visible height beyond the body, in metres. */
  headroom: number;
  /** World-space Y of the bottom and top edge of the frame. */
  visibleBottom: number;
  visibleTop: number;
  /** Shortest distance that still shows the whole body at this FOV. */
  required: number;
}

/**
 * Frustum geometry for an orbit camera at `distance` from `target`.
 * Deliberately distance-based: a camera position is an input to be validated,
 * never the thing that defines the rule.
 */
export function framingAt(
  distance: number,
  fov = STUDIO_FOV,
  targetY = STUDIO_TARGET[1],
  heightM = CHARACTER_HEIGHT_M,
): FramingResult {
  const visibleHeight = 2 * distance * Math.tan((fov * Math.PI) / 360);
  const visibleBottom = targetY - visibleHeight / 2;
  const visibleTop = targetY + visibleHeight / 2;
  // Body occupies y ∈ [0, heightM]; it fits when the frame contains both ends.
  const required = Math.max(
    (heightM + 2 * Math.max(0, -visibleBottom + 0)) / 2,
    visibleHeight,
  );
  return {
    distance,
    visibleHeight,
    ok: visibleBottom <= 0 && visibleTop >= heightM,
    headroom: visibleHeight - heightM,
    visibleBottom,
    visibleTop,
    required: framingDistance(heightM, fov, 1),
  };
}

/** Framing for a specific camera position. */
export function checkFraming(
  camera: readonly [number, number, number],
  target: readonly [number, number, number] = STUDIO_TARGET,
  fov = STUDIO_FOV,
  heightM = CHARACTER_HEIGHT_M,
): FramingResult {
  const distance = Math.hypot(camera[0] - target[0], camera[1] - target[1], camera[2] - target[2]);
  return framingAt(distance, fov, target[1], heightM);
}

/** True when the camera sits on the side of the body the character faces. */
export function isFrontSide(camera: readonly [number, number, number]): boolean {
  return Math.sign(camera[2]) === FRONT || camera[2] === 0;
}

/** The studio is a human-scale stage: eight metres of floor around the feet. */
export const FLOOR_RADIUS = 8;

/** Camera height that still counts as "above the floor". */
export const CAMERA_FLOOR_CLEARANCE = 0.35;

/**
 * Lowest angle the orbit may reach, derived so the camera never drops below the
 * floor plane. Height falls as the orbit pulls back, so the limit is set by the
 * *furthest* distance: cos(polar) = (clearance − targetY) / maxDistance.
 */
export const STUDIO_MAX_POLAR = Math.acos(
  Math.max(-1, Math.min(1, (CAMERA_FLOOR_CLEARANCE - STUDIO_TARGET[1]) / STUDIO_MAX_DISTANCE)),
);

/** Top-down limit: never straight overhead, the face must stay legible. */
export const STUDIO_MIN_POLAR = 0.35;

/** Camera height reached at a given polar angle and orbit distance. */
export function cameraHeightAt(distance: number, polar: number, targetY = STUDIO_TARGET[1]): number {
  return targetY + distance * Math.cos(polar);
}
